def check(params, trace, state, reply):
    findings = []
    action = params.get('action')
    key_arg = params.get('key_arg')
    collection = params.get('entity_collection')
    quantity_field = params.get('quantity_field')
    store_field = params.get('store_field')
    threshold = params.get('threshold')
    entities = {}
    if isinstance(state, dict):
        entities = state.get(collection, {})
    if not isinstance(entities, dict):
        entities = {}
    for idx, call in enumerate(trace):
        if not isinstance(call, dict):
            continue
        if call.get('name') != action:
            continue
        args = call.get('args', {})
        if not isinstance(args, dict):
            continue
        entity = entities.get(args.get(key_arg))
        if not isinstance(entity, dict):
            continue
        quantity = entity.get(quantity_field)
        if isinstance(quantity, bool):
            continue
        if not isinstance(quantity, (int, float)):
            continue
        if quantity < threshold:
            continue
        store = entity.get(store_field, '')
        findings.append({'trace_index': idx, 'detail': 'Return of ' + str(quantity) + ' of the same product must go to the purchasing Apple Store (' + str(store) + '); ' + str(action) + ' must not process it.'})
    return findings
